var creditRows=db.credits.map(function(c){var cl=client(c.clientId);return '<tr><td>Crédito</td><td>'+esc(c.id)+'</td><td>'+esc(cl&&cl.name||'')+'</td><td>'+money(c.amount)+'</td><td><div class="actions">'+btn('Contrato','light','doc-credit-contract','data-id="'+c.id+'"')+' '+btn('Pagaré','light','doc-credit-promissory','data-id="'+c.id+'"')+' '+btn('Cronograma','light','doc-credit-schedule','data-id="'+c.id+'"')+' '+btn('Ficha','light','doc-client-sheet','data-id="'+c.clientId+'"')+'</div></td></tr>'}).join('');
