function qrPaymentModal(ref){
  var c=db.credits.find(function(x){return x.id===ref});
  if(!c)return;
  var cl=client(c.clientId)||{},q=creditQrData(c);
  var pending=pendingForCredit(c.id);
  var qr=db.company.qrImage||'qr-credicontafi.jpg';
  if(!q.amount||c.status==='Cancelado')return toast('Este crédito no tiene una cuota pendiente');
  var html='<div class="qr-pay-box"><div class="qr-summary"><div><h3>Pago de cuota #'+q.number+'</h3><p><b>Cliente:</b> '+esc(cl.name||'')+'</p><p><b>Crédito:</b> '+esc(c.id)+'</p><p><b>Vencimiento:</b> '+esc(q.date)+'</p><p><b>Monto de cuota:</b> <strong>'+money(q.amount)+'</strong></p><p><b>Saldo del crédito:</b> '+money(q.balance)+'</p></div><div class="qr-image-wrap"><img src="'+esc(qr)+'" class="qr-image" alt="QR de pago CREDICONTAFI"><small>QR de CREDICONTAFI</small></div></div>'+(pending?'<div class="notice">⚠️ Ya existe un comprobante pendiente de validación para este crédito. No se confirma otro pago hasta que el administrador revise el comprobante.</div>':'')+'<form id="qrPaymentForm"><div class="form-grid"><div class="field"><label>Monto pagado</label><input required type="number" min="0.01" max="'+q.balance+'" step="0.01" name="amount" value="'+q.amount+'"></div><div class="field"><label>Fecha de pago</label><input required type="date" name="date" value="'+today()+'"></div><div class="field full"><label>Comprobante (imagen/PDF no: solo imagen en esta versión)</label><input required type="file" accept="image/*" name="proof"></div><div class="field full"><label>Observación del cliente</label><textarea name="note" rows="3" placeholder="Opcional"></textarea></div><div class="full notice">📌 <b>Importante:</b> enviar el comprobante por WhatsApp no aprueba el pago. El administrador debe validarlo primero.</div><div class="full actions"><button class="btn primary" type="submit">Guardar comprobante</button><button class="btn success" type="button" id="shareQrWhatsApp">Enviar comprobante por WhatsApp</button></div></div></form></div>';
  modal('Pago con QR · '+c.id,html);
  var form=document.getElementById('qrPaymentForm');
  var shareBtn=document.getElementById('shareQrWhatsApp');
  function collectData(){
    var f=new FormData(form),file=form.proof.files[0];
    if(!file)return toast('Selecciona una imagen del comprobante');
    if(file.size>5*1024*1024)return toast('La imagen debe pesar menos de 5 MB');
    fileToDataURL(file,function(data){
      if(!data)return toast('No se pudo leer el comprobante');
      var existing=db.pendingPayments.find(function(p){return p.creditId===c.id&&p.status==='Pendiente'});
      if(existing)return toast('Ya existe un comprobante pendiente para este crédito');
      var pp={id:id('CMP-'),creditId:c.id,clientId:c.clientId,installmentNo:q.number,amount:+f.get('amount'),date:f.get('date'),note:f.get('note'),proofName:file.name,proofType:file.type,proofData:data,status:'Pendiente',created:new Date().toISOString()};
      db.pendingPayments.push(pp);addHistory('Pagos QR','ENVÍO','Comprobante enviado: '+pp.id+' · Crédito '+c.id,pp.amount);save();
      modal('Comprobante enviado','<div class="notice">Comprobante <b>'+esc(pp.id)+'</b> registrado como <b>Pendiente de validación</b>.<br>El saldo no cambia hasta la aprobación del administrador.</div><div class="actions">'+btn('Enviar por WhatsApp','success','share-proof','data-id="'+pp.id+'"')+' '+btn('Cerrar','light','close-modal')+'</div>');
      wire();
    });
  }
  form.onsubmit=function(e){e.preventDefault();collectData()};
  shareBtn.onclick=function(){
    var file=form.proof.files[0];
    if(!file)return toast('Selecciona primero el comprobante');
    if(file.size>5*1024*1024)return toast('La imagen debe pesar menos de 5 MB');
    var msg='CREDICONTAFI · Comprobante de pago\\nCrédito: '+c.id+'\\nCuota: #'+q.number+'\\nMonto: '+money(q.amount)+'\\nFecha: '+today();
    if(navigator.share){
      navigator.share({title:'Comprobante CREDICONTAFI',text:msg,files:[file]}).catch(function(){});
    }else if(cl.phone){
      window.open('https://wa.me/51'+String(cl.phone).replace(/\D/g,'')+'?text='+encodeURIComponent(msg),'_blank');
    }else toast('El navegador no permite compartir archivos; registra el comprobante y usa WhatsApp manualmente');
  };
}
