function approveProof(ref){
  var p=db.pendingPayments.find(function(x){return x.id===ref});if(!p||p.status!=='Pendiente')return;
  var c=db.credits.find(function(x){return x.id===p.creditId});if(!c)return;
  ensureCreditSchedule(c);
  var r=c.schedule.find(function(x){return Number(x.n)===Number(p.installmentNo)&&x.status!=='Pagada'})||nextInstallment(c);
  if(!r)return toast('La cuota ya fue pagada');
  var amount=Math.min(Number(p.amount)||0,Number(c.balance)||0);
  if(amount<=0)return toast('El saldo del crédito ya está cancelado');
  r.paidAmount=Number(r.paidAmount||0)+amount;
  r.paymentId=id('PAY-');
  if(r.paidAmount+0.009>=Number(r.payment||0))r.status='Pagada';else r.status='Parcial';
  c.balance=+Math.max(0,Number(c.balance)-amount).toFixed(2);
  var next=nextInstallment(c);c.nextPayment=next?next.date:'—';if(c.balance===0)c.status='Cancelado';
  db.payments.push({id:r.paymentId,creditId:c.id,clientId:p.clientId,installmentNo:r.n,amount:amount,date:p.date,source:'Comprobante QR',proofId:p.id});
  p.status='Aprobado';p.approvedAt=new Date().toISOString();p.approvedAmount=amount;
  addHistory('Pagos QR','APROBACIÓN','Pago confirmado: '+p.id+' · Crédito '+c.id+' · Cuota #'+r.n,amount);save();closeModal();render('payments');toast('Pago confirmado y saldo actualizado');
}
