    var js=db.funds.juntas.map(function(j){return '<tr><td>'+esc(j.id)+'</td><td>'+esc(j.name)+'</td><td><div class="actions">'+btn('Resumen junta','light','doc-junta-full','data-id="'+j.id+'"')+'</div></td></tr>'}).join('');
    var inv=db.funds.investments.map(function(i){return '<tr><td>'+esc(i.id)+'</td><td>'+esc(i.investorName||'No registrado')+'</td><td>'+money(i.capital)+'</td><td><div class="actions">'+btn('Acuerdo','light','doc-investment-agreement','data-id="'+i.id+'"')+btn('Ficha','light','doc-investment-sheet','data-id="'+i.id+'"')+btn('Constancia','light','doc-investment-receipt','data-id="'+i.id+'"')+btn('Recibo capital','light','doc-investment-capital','data-id="'+i.id+'"')+btn('Rendimientos','light','doc-investment-schedule','data-id="'+i.id+'"')+btn('Recibo rendimiento','light','doc-investment-return','data-id="'+i.id+'"')+btn('Estado','light','doc-investment-statement','data-id="'+i.id+'"')+'</div></td></tr>'}).join('');
    var hist=db.documents.slice().reverse().slice(0,150).map(function(d){return '<tr><td>'+new Date(d.date).toLocaleString('es-PE')+'</td><td>'+esc(d.id)+'</td><td>'+esc(d.type)+'</td><td>'+esc(d.ref)+'</td></tr>'}).join('');
    return '<div class="page-head"><div><h1 class="page-title">Documentos</h1><p class="sub">Generación automática desde los datos registrados.</p></div></div><div class="grid"><div class="card metric blue"><div class="label">Documentos generados</div><div class="value">'+db.documents.length+'</div></div><div class="card metric green"><div class="label">Créditos</div><div class="value">'+db.credits.length+'</div></div><div class="card metric purple"><div class="label">Participantes</div><div class="value">'+db.funds.members.length+'</div></div><div class="card metric orange"><div class="label">Inversiones</div><div class="value">'+db.funds.investments.length+'</div></div></div><div class="card"><h3>📄 Créditos</h3><div class="table-wrap"><table class="table"><tr><th>Crédito</th><th>Cliente</th><th>Capital</th><th>Documentos</th></tr>'+cr+'</table></div></div><div class="card"><h3>👨‍👩‍👧 Juntas y familiares</h3><div class="table-wrap"><table class="table"><tr><th>Participante</th><th>Junta</th><th>Documentos</th></tr>'+mem+'</table></div><h4>Juntas</h4><table class="table"><tr><th>Código</th><th>Junta</th><th>Documento</th></tr>'+js+'</table></div><div class="card"><h3>📈 Inversiones</h3><div class="table-wrap"><table class="table"><tr><th>Inversión</th><th>Inversionista</th><th>Capital</th><th>Documentos</th></tr>'+inv+'</table></div></div><div class="card"><h3>🗂️ Historial documental</h3><div class="table-wrap"><table class="table"><tr><th>Fecha</th><th>N.° documento</th><th>Tipo</th><th>Referencia</th></tr>'+hist+'</table></div></div>';
